<#
 WSL2 嵌套 GNOME 桌面 —— 一键安装脚本（自包含）
 适用：Windows 10 22H2+ / Windows 11 + WSL2 + WSLg + Ubuntu 26.04

 用法（Windows PowerShell，普通权限即可）：
   powershell -ExecutionPolicy Bypass -File .\install.ps1

 可选参数：
   -Distro Ubuntu      指定 WSL 发行版名
   -SkipApt            跳过 apt 安装（已经装过桌面组件时）
   -NoStart            安装完不自动启动桌面
   -DryRun             只检查/打印计划，不做任何改动

 说明：脚本内已内嵌全部配置内容，不需要联网下载本仓库。
#>
param(
    [string]$Distro = 'Ubuntu',
    [switch]$SkipApt,
    [switch]$NoStart,
    [switch]$DryRun
)

$ErrorActionPreference = 'Stop'
$env:WSL_UTF8 = '1'

function Step([string]$m) { Write-Host "`n===== $m =====" -ForegroundColor Cyan }
function Info([string]$m) { Write-Host "  $m" }
function Warn([string]$m) { Write-Host "  [!] $m" -ForegroundColor Yellow }
function Fail([string]$m) { Write-Host "`n[失败] $m" -ForegroundColor Red; exit 1 }
function Run-Wsl([string]$cmd) { return (& wsl.exe -d $Distro -- bash -lc $cmd 2>$null) }

