Step '1/7 检查 WSL'
$wslVersion = (& wsl.exe --version 2>$null) -join "`n"
if (-not $wslVersion) {
    Fail '未检测到 WSL2。请先在“管理员 PowerShell”执行：wsl --install，重启后再运行本脚本。'
}
Info (($wslVersion -split "`n") | Where-Object { $_ -match 'WSL|Windows' } | Select-Object -First 3)

if (((Run-Wsl 'echo ok') -join '') -notmatch 'ok') {
    Fail "无法进入 WSL 发行版 '$Distro'。请确认已安装（管理员 PowerShell：wsl --install -d Ubuntu）并完成首次用户创建；如发行版名不同请用 -Distro 指定。"
}
Info "发行版 $Distro 可用"

Step '2/7 检查 WSLg 图形支持'
$display = (Run-Wsl 'printf "%s" "$DISPLAY"') -join ''
if (-not $display) {
    Warn 'WSLg 未启用（DISPLAY 为空），尝试自动修复 .wslconfig'
    $cfg = Join-Path $env:USERPROFILE '.wslconfig'
    if (Test-Path $cfg) { Copy-Item $cfg "$cfg.bak" -Force; $content = Get-Content $cfg -Raw } else { $content = '' }
    if ($content -match 'guiApplications\s*=') {
        $content = $content -replace 'guiApplications\s*=\s*false', 'guiApplications=true'
    } elseif ($content -match '(?m)^\[wsl2\]\s*$') {
        $content = $content -replace '(?m)^\[wsl2\]\s*$', "[wsl2]`r`nguiApplications=true"
    } else {
        $content = "$content`r`n[wsl2]`r`nguiApplications=true`r`n"
    }
    if (-not $DryRun) {
        Set-Content -Path $cfg -Value $content -Encoding utf8
        Info "已写入 .wslconfig：$cfg"
        wsl.exe --shutdown
        Start-Sleep -Seconds 8
    }
    $display = (Run-Wsl 'printf "%s" "$DISPLAY"') -join ''
    if (-not $display) {
        Fail 'WSLg 仍未启用。请确认 Windows 版本（Win11 或 Win10 22H2+），并在管理员 PowerShell 运行：wsl --update，然后重启电脑/重试。'
    }
}
Info "WSLg 正常（DISPLAY=$display）"

Step '3/7 部署脚本到 WSL'
if ($DryRun) {
    Info '（DryRun）跳过部署'
} else {
    $b64 = ($PayloadBase64 -replace '\s', '')
    $b64Path = Join-Path $env:TEMP 'wsl-desktop-payload.b64'
    Set-Content -Path $b64Path -Value $b64 -NoNewline -Encoding ascii
    $out = ((Get-Content $b64Path -Raw) | wsl.exe -d $Distro -u root -- bash -lc "base64 -d > /tmp/wsl-desktop.tar.gz && mkdir -p /opt && rm -rf /opt/wsl-desktop && tar -xzf /tmp/wsl-desktop.tar.gz -C /opt && find /opt/wsl-desktop -type f \( -name '*.sh' -o -name '*.js' -o -name '*.json' -o -name '*.service' \) -exec sed -i 's/\r`$//' {} + && echo EXTRACTED") -join "`n"
    if ($out -notmatch 'EXTRACTED') { Fail '脚本部署失败（解包异常）。' }
    Info '脚本已部署：WSL:/opt/wsl-desktop'
}

Step '4/7 安装桌面组件（首次约 2~5 GB，需要耐心）'
if ($SkipApt) {
    Info '已跳过（-SkipApt）'
} elseif ($DryRun) {
    Info '（DryRun）将执行 apt-get install ubuntu-desktop mutter-dev-bin'
} else {
    & wsl.exe -d $Distro -u root -- bash -lc 'export DEBIAN_FRONTEND=noninteractive; apt-get update -qq && apt-get install -y ubuntu-desktop mutter-dev-bin'
    if ($LASTEXITCODE -ne 0) { Fail 'apt 安装失败，请检查网络与磁盘空间后重试。' }
    Info '桌面组件安装完成'
}

Step '5/7 配置桌面 / 剪贴板 / 声音'
if ($DryRun) {
    Info '（DryRun）将运行 install-audio.sh / install-clipbridge.sh / setup-snap-audio.sh'
} else {
    & wsl.exe -d $Distro -u root -- bash /opt/wsl-desktop/audio/install-audio.sh
    if ($LASTEXITCODE -ne 0) { Fail '音频环境配置失败。' }
    & wsl.exe -d $Distro -u root -- bash /opt/wsl-desktop/clipboard/install-clipbridge.sh
    if ($LASTEXITCODE -ne 0) { Fail '剪贴板桥安装失败。' }
    & wsl.exe -d $Distro -- bash -lc 'systemctl --user daemon-reload; systemctl --user enable wsl-clipbridge >/dev/null 2>&1; systemctl --user restart wsl-clipbridge; systemctl --user mask pipewire-pulse.socket pipewire-pulse.service 2>/dev/null'
    & wsl.exe -d $Distro -- bash /opt/wsl-desktop/audio/setup-snap-audio.sh
    Info '配置完成'
}

Step '6/7 启动桌面'
if ($NoStart) {
    Info "已跳过（-NoStart）。稍后可在 WSL 里运行 ~/start-desktop.sh，或参考 TROUBLESHOOTING.md"
} elseif ($DryRun) {
    Info '（DryRun）将启动桌面'
} else {
    & wsl.exe -d $Distro -- bash -lc '~/start-desktop.sh'
    Start-Sleep -Seconds 20
    $check = (Run-Wsl '~/start-desktop.sh --check 2>&1') -join "`n"
    $check -split "`n" | Where-Object { $_ -match '声音服务|剪贴板代理|剪贴板桥|gnome-shell' } | ForEach-Object { Info $_ }
    $shell = ((Run-Wsl 'pgrep -c -x gnome-shell 2>/dev/null || echo 0') -join '').Trim()
    Info "gnome-shell 进程数：$shell"
    if ($shell -eq '0') {
        Warn '桌面没有启动成功。请运行 oneclick/restart-desktop.ps1，或参考 TROUBLESHOOTING.md。'
    } else {
        Info '桌面已启动，窗口标题为「Mutter Development Kit」'
    }
}

Step '7/7 完成'
Write-Host @"

安装完成！

以后常用：
  启动桌面：   powershell -ExecutionPolicy Bypass -File .\start-desktop.ps1        # 后台启动，不占终端
  查看状态：   powershell -ExecutionPolicy Bypass -File .\start-desktop.ps1 -Status
  停止桌面：   powershell -ExecutionPolicy Bypass -File .\start-desktop.ps1 -Stop
  修复一切：   wsl -d $Distro -- bash -lc "~/start-desktop.sh --fix"
  WSL 里也可以：~/start-desktop.sh（启动） / --check / --stop / --foreground
  修声音：     powershell -ExecutionPolicy Bypass -File .\fix-audio.ps1
  重开桌面：   powershell -ExecutionPolicy Bypass -File .\restart-desktop.ps1
  排障手册：   TROUBLESHOOTING.md

注意：
  * 桌面窗口关掉 = 桌面退出，重开即可；
  * 启动桌面是后台启动，Windows 窗口/WSL 终端都会立即释放，不会被占用；
  * 任意目录启动（幂等、不占终端）：wsl -d $Distro -- bash -lc "~/start-desktop.sh"
    也可以双击 oneclick\start-desktop.cmd（自动定位，和当前目录无关）；
    不要反复手动执行 systemd-run 同一单元——单元已存在时会报 already loaded，属正常；
  * 每次运行 ~/start-desktop.sh 都会自动修复声音（热重启卡死的 WSLg 音频，约 3 秒）
    并拉起剪贴板代理；「没声音 / 没剪贴板」先跑 ~/start-desktop.sh --fix 就行，通常不用重启 WSL；
  * 从 Ubuntu 桌面里启动的应用会留在桌面窗口内（不再变成 Windows 上单独的窗口）；
    如果 apt 升级过 mutter，重跑一次 ~/start-desktop.sh 会自动修复（TROUBLESHOOTING 4.9）；
  * 桌面崩溃后 GNOME 会自动禁用扩展（复制粘贴会失效），跑一次 ~/start-desktop.sh 会自动恢复
    （TROUBLESHOOTING 6 ④）；
  * 声音仍可能周期性卡死（WSLg 的 bug），Windows 侧代理每 20 秒看门狗兜底；
  * 剪贴板为纯文本双向（约 0.5~2 秒延迟），日志：
    C:\Users\Public\wsl-desktop-clip\agent.log
"@